// Apify async: start run → poll status → fetch dataset — 2026-06-19 UTC+5
const cfg = $('Set Search Parameters').first().json;
const token = $env.APIFY_TOKEN;
const http = this.helpers.httpRequest;

if (!token) throw new Error('APIFY_TOKEN env var missing');

const input = {
  searchStringsArray: [`${cfg.keyword} in ${cfg.location}`],
  maxCrawledPlacesPerSearch: Number(cfg.limit) || 50,
  includeReviews: false,
  includeImage: false,
  exportPlaceUrls: false,
  subTitle: false
};

// Step 1: Start run (waitForFinish=0 = return immediately)
const startRes = await http({
  method: 'POST',
  url: `https://api.apify.com/v2/acts/compass~crawler-google-places/runs?token=${encodeURIComponent(token)}&waitForFinish=0`,
  headers: { 'Content-Type': 'application/json' },
  body: input,
  json: true
});

const runId = startRes.data?.id;
if (!runId) throw new Error('Apify did not return a run id');

// Step 2: Poll until complete (max 15 min)
const MAX_WAIT_MS = 15 * 60 * 1000;
const POLL_MS = 10000;
const t0 = Date.now();

let run = startRes.data;
const terminal = ['SUCCEEDED', 'FAILED', 'ABORTED', 'TIMED-OUT'];

while (!terminal.includes(run.status)) {
  if (Date.now() - t0 > MAX_WAIT_MS) {
    throw new Error(`Apify run ${runId} timed out after 15 minutes (status: ${run.status})`);
  }
  await new Promise(r => setTimeout(r, POLL_MS));

  const statusRes = await http({
    method: 'GET',
    url: `https://api.apify.com/v2/actor-runs/${runId}?token=${encodeURIComponent(token)}`,
    json: true
  });
  run = statusRes.data || statusRes;
}

if (run.status !== 'SUCCEEDED') {
  throw new Error(`Apify run ${run.status}: ${run.statusMessage || 'unknown error'}`);
}

// Step 3: Fetch dataset items
const datasetId = run.defaultDatasetId;
const items = await http({
  method: 'GET',
  url: `https://api.apify.com/v2/datasets/${datasetId}/items?token=${encodeURIComponent(token)}`,
  json: true
});

const businesses = Array.isArray(items) ? items : (items?.items || []);

return [{ json: { items: businesses, runId, count: businesses.length } }];

const raw = $input.first().json;

// Handle all Apify response structures
let businesses;
if (Array.isArray(raw)) {
  businesses = raw;
} else if (Array.isArray(raw.items)) {
  businesses = raw.items;
} else {
  businesses = [raw];
}

// Split + Normalize in one step
return businesses.map(business => ({
  json: {
    // Identity
    external_id:   business.placeId || business.phoneUnformatted || '',
    source:        'gmb',

    // Core business info
    business_name: business.title || '',
    category:      business.categoryName || '',
    phone:         business.phone || '',
    address:       business.street || business.address || '',
    city:          business.city || '',
    state:         business.state || '',
    country:       business.countryCode || 'AU',
    website_url:   business.website || '',

    // Performance (may be null — filled by WF2 later)
    rating:        business.totalScore || null,
    review_count:  business.reviewsCount || null,

    // Pipeline
    status:        'new',
    search_query:  `${business.categoryName || ''} in ${business.city || ''}`
  }
}));

